questionvariables.text:
cx : 7;
cy : 6;
templates : [
  [[-1.6,-1.5],[1.6,-1.5],[0,2.6]],
  [[0,-2.4],[1.5,0.2],[0,2.6],[-1.5,0.2]],
  [[-2.2,-1.6],[2.2,-1.6],[1.2,1.8],[-1.2,1.8]],
  [[-1.7,-1.8],[1.7,-1.8],[1.7,0.6],[0,2.4],[-1.7,0.6]],
  [[0,-2.2],[1.8,-0.8],[1.4,1.2],[0,2.2],[-1.4,1.2],[-1.8,-0.8]]
];
ti : rand(5) + 1;
baseV : templates[ti];
phi : rand(360);
ta : rand([true, false]);
ncase : if ta then 0 else rand(3) + 1;   /* 0 axis (yes); 1 wrong angle; 2 off-centre; 3 broken */
pj : rand(length(baseV)) + 1;
locV : if ncase = 3
       then append(makelist(baseV[k], k, 1, pj - 1), [baseV[pj] + [1.2, 0.8]], makelist(baseV[k], k, pj + 1, length(baseV)))
       else baseV;
rad(a) := float(a * %pi / 180);
cphi : cos(rad(phi));
sphi : sin(rad(phi));
worldpt(p) := [float(cx + p[1]*cphi - p[2]*sphi), float(cy + p[1]*sphi + p[2]*cphi)];
worldV : map(worldpt, locV);
axisAngle : 90 + phi;
delta : ([30,45,60,90,120,135])[rand(6)+1] * (if rand(2) = 0 then 1 else -1);
alpha : if ncase = 1 then axisAngle + delta else axisAngle;
offd : if ncase = 2 then 1.7 * (if rand(2) = 0 then 1 else -1) else 0;
LL : 5.2;
ca : cos(rad(alpha));
sa : sin(rad(alpha));
ppx : cos(rad(alpha + 90));
ppy : sin(rad(alpha + 90));
lineA : [float(cx + LL*ca + offd*ppx), float(cy + LL*sa + offd*ppy)];
lineB : [float(cx - LL*ca + offd*ppx), float(cy - LL*sa + offd*ppy)];
reasonTxt : if ncase = 0
      then "Yes. Folding the shape along the dashed line maps it exactly onto itself, so the line is a line of symmetry."
    elseif ncase = 1
      then "No. This shape does have a line of symmetry, but the dashed line is not it: the dashed line is at the wrong angle, so the two halves are not mirror images."
    elseif ncase = 2
      then "No. A line of symmetry must pass through the centre of the shape. The dashed line is parallel to the true axis of symmetry but shifted to one side, so it does not split the shape into mirror-image halves."
    else "No. This shape is not symmetric at all: there is no line you could fold along to make the two halves match, and reflecting it in the dashed line does not return the original.";
